// 把 src/*.js 按文件名顺序拼成 app.js（同一个全局作用域，跟以前单文件时行为完全一致）。
// 源码只改 src/，app.js 是产物（已 gitignore）。
//   node bundle.js          拼一次
//   node bundle.js --watch  监听 src/，改一下拼一下（本地开发用）
const fs = require("fs");
const path = require("path");

const SRC = path.join(__dirname, "src");
const OUT = path.join(__dirname, "app.js");

function bundle() {
  const files = fs.readdirSync(SRC).filter((f) => f.endsWith(".js")).sort();
  const parts = files.map((f) => {
    const body = fs.readFileSync(path.join(SRC, f), "utf8");
    // 每个文件前放一行路标：浏览器报错只给 app.js 的行号，靠它回到 src 里对应的文件
    return `/* >>> src/${f} */\n${body}${body.endsWith("\n") ? "" : "\n"}`;
  });
  const out = "/* GENERATED by bundle.js — 别直接改这个文件，改 src/*.js */\n" + parts.join("");
  fs.writeFileSync(OUT, out, "utf8");
  return files.length;
}

module.exports = { bundle };

if (require.main === module) {
  const n = bundle();
  console.log(`app.js bundled from ${n} files.`);
  if (process.argv.includes("--watch")) {
    let timer = null;
    fs.watch(SRC, () => {
      clearTimeout(timer);
      timer = setTimeout(() => { try { bundle(); console.log("rebundled " + new Date().toLocaleTimeString()); } catch (e) { console.error(e); } }, 80);
    });
    console.log("watching src/ …");
  }
}
